<script setup lang="ts">
import { computed, nextTick, onUnmounted, ref } from 'vue';
import { ElTooltip } from 'element-plus/es/components/tooltip/index.mjs';
import 'element-plus/es/components/tooltip/style/css';
import { usePreview, type KnowledgeDoc } from '../../features/preview/usePreviewStore';
import PageHeading from '../../features/preview/components/PageHeading.vue';
import Icon from '../../features/workbench/components/WorkbenchIcon.vue';
const s=usePreview(),text=ref(''),busy=ref(false),selected=ref<number|null>(null),turns=ref<{id:number;question:string;answer:string;decision:string;sources:{doc:KnowledgeDoc;chunk:string;index:number;score:number}[]}[]>([]),scroll=ref<HTMLElement|null>(null);
let generation=0;onUnmounted(()=>generation++);
const current=computed(()=>turns.value.find(t=>t.id===selected.value));
async function send(){const q=text.value.trim();if(!q||busy.value)return;busy.value=true;text.value='';const run=++generation;const cleaned=q.replace(/[，。？！、\s]/g,'');const words=[...new Set(cleaned.length<2?[cleaned]:Array.from({length:cleaned.length-1},(_,i)=>cleaned.slice(i,i+2)))];
const sources=s.effectiveDocs.value.flatMap(doc=>doc.chunks.map((chunk,index)=>({doc,chunk,index}))).map(item=>({...item,score:words.length?words.filter(w=>item.chunk.includes(w)).length/words.length:0})).filter(item=>item.score>0&&item.score>=Number(s.retrieval.score)).sort((a,b)=>b.score-a.score).slice(0,s.retrieval.topK);await new Promise(r=>setTimeout(r,700));if(run!==generation)return;
const human=/人工|客服接入|投诉/.test(q),business=/退款|退货|换货|修改地址|取消订单/.test(q);const decision=human?'建议转人工（仅展示判断）':business?'需要核实订单与办理条件（仅展示判断）':sources.length?'知识问答':'需要更多信息';
const answer=human?'您的诉求需要人工客服确认。':business?'请提供需要处理的订单，以及具体商品和诉求。我会先核实订单状态，再根据当前适用规则说明下一步。':sources.length?`根据当前有效知识，可参考以下内容：\n${sources[0].chunk.replace(/^#+\s?.*\n/,'').slice(0,230)}`:'当前已发布知识中没有找到明确匹配的内容，请补充商品、订单或具体问题。';
const turn={id:Date.now(),question:q,answer,decision,sources};turns.value.push(turn);selected.value=turn.id;busy.value=false;await nextTick();scroll.value?.scrollTo({top:scroll.value.scrollHeight,behavior:'smooth'});}
function clear(){generation++;busy.value=false;turns.value=[];selected.value=null;text.value='';}
</script>
<template><div class="pv-page pv-recall-page"><PageHeading title="召回测试" description="使用当前已发布且有效的全店知识，连续试问并查看每次引用的切片。" eyebrow="AI 与知识"/><div class="pv-notice"><Icon name="InfoFilled"/><span>使用当前已发布且有效的知识。未发布内容不参与测试；转人工只展示判断，不创建待接会话。</span></div><div class="pv-recall-grid"><section class="pv-card pv-recall-chat"><div class="pv-panel-heading"><strong>试问 AI</strong><div class="pv-card-actions"><span class="pv-panel-meta">{{s.effectiveDocs.value.length}} 篇有效知识 · Top K {{s.retrieval.topK}}</span><button class="wb-btn" :disabled="!turns.length&&!busy" @click="clear"><Icon name="Refresh"/>清空对话</button></div></div><div ref="scroll" class="pv-recall-messages"><div v-if="!turns.length&&!busy" class="pv-recall-welcome"><span class="pv-welcome-icon"><Icon name="MagicStick"/></span><h3>看看 AI 会怎样回答</h3><p>输入一个真实的客服问题，右侧查看命中的知识片段。</p><button v-for="q in ['这条裤子还能补货吗？','我想退货，应该怎么申请？','我想找人工客服']" :key="q" @click="text=q;send()">{{q}} <span>↗</span></button></div><article v-for="t in turns" :key="t.id" class="pv-test-turn" :class="{selected:selected===t.id}"><div class="pv-test-question">{{t.question}}</div><button class="pv-test-answer" @click="selected=t.id"><span class="pv-tag blue">AI</span><p>{{t.answer}}</p><span class="pv-test-decision">{{t.decision}}</span><small>{{t.sources.length}} 个知识片段 · 点击查看依据</small></button></article><div v-if="busy" class="pv-test-loading"><Icon name="Loading" spin/>正在检索知识…</div></div><form class="pv-recall-composer" @submit.prevent="send"><textarea v-model="text" rows="2" maxlength="2000" placeholder="输入客户问题…" aria-label="测试问题" @keydown.enter.exact.prevent="send"/><button class="wb-btn primary" :disabled="!text.trim()||busy" type="submit"><Icon name="Position"/>发送</button></form></section><section class="pv-card pv-recall-sources"><div class="pv-panel-heading"><strong>本次召回切片</strong><span>{{current?.sources.length||0}} 条</span></div><div v-if="current?.sources.length" class="pv-source-list"><article v-for="item in current.sources" :key="`${item.doc.id}-${item.index}`" class="pv-chunk-card"><div><span class="pv-tag blue">切片 {{item.index+1}}</span><strong>{{item.doc.title}}</strong><el-tooltip content="相关性得分，范围 0–1；越高表示越相关，不代表回答正确率。"><span class="pv-tag green pv-score" tabindex="0">Score {{item.score.toFixed(2)}}</span></el-tooltip></div><p>{{item.chunk}}</p><small class="pv-muted">{{s.categories.value.find(c=>c.id===item.doc.categoryId)?.name}}</small></article></div><div v-else class="pv-empty"><Icon name="Reading"/><strong>{{current?'本次没有命中知识片段':'知识依据会显示在这里'}}</strong><span>{{current?'可以补充更具体的问题再试一次':'完成一次提问后，点击回复切换查看'}}</span></div></section></div></div></template>
